content.content:
    };
  }
  return { kind: "none", detail: "no active host firewall — 80/443 are already reachable" };
}

/**
 * HTTP-probe one URL from the target itself and return its status code
 * ("000" = nothing answered at all).
 *
 * `resolve` pins the hostname to 127.0.0.1 with `curl --resolve`, which sends the
 * real Host header AND the real TLS SNI while never leaving the box. That is what
 * makes this a genuine test of "will the customer's domain serve once DNS points
 * here" — a plain port check proves only that something is listening, which is
 * exactly how a migration can report success while the site returns 502 or the
 * stock welcome page. `-k` because at probe time the name still resolves
 * elsewhere; we are testing that the vhost matches and answers, not the chain.
 */
async function httpProbe(
  conn: Client,
  url: string,
  resolve?: { domain: string; port: number }
): Promise<{ code: string; body: string }> {
  const res = resolve ? `--resolve ${resolve.domain}:${resolve.port}:127.0.0.1 ` : "";
  // The BODY is fetched as well as the status, because a status code alone
  // cannot tell a real site from the stock Apache/nginx default page — see
  // defaultPageReason. It lands in a `mktemp` file rather than a fixed /tmp
  // name: on a migrated multi-user box a predictable path under /tmp is a
  // symlink-overwrite waiting to happen, and this engine never takes a
  // destructive risk with the customer's files.
  const r = await sh(
    conn,
    `f=$(mktemp 2>/dev/null || echo /dev/null); ` +
      `c=$(curl -sS -k --max-time 12 ${res}-o "$f" -w '%{http_code}' ${url} 2>/dev/null); ` +
      `[ -n "$c" ] || c=000; printf 'NXCODE:%s\\n' "$c"; head -c 4096 "$f" 2>/dev/null; ` +
      `[ "$f" = /dev/null ] || rm -f "$f"`,
    SETUP_TIMEOUT_MS
  );
  const out = String(r.stdout ?? "");
  const m = /NXCODE:(\d{3})/.exec(out);
  const nl = out.indexOf("\n");
  return { code: m ? m[1] : "000", body: probeBody(nl < 0 ? "" : out.slice(nl + 1)) };
}

/** Status-code-only probe (unchanged contract) — now sharing one code path. */
async function httpCode(conn: Client, url: string, resolve?: { domain: string; port: number }): Promise<string> {
  return (await httpProbe(conn, url, resolve)).code;
}

/**
 * Bound a response body for pattern-matching. Deliberately NOT `clean()`:
 * `clean` strips ALL control characters including newlines, which would glue
 * "Apache2 Debian Default\nPage" into "Apache2 Debian DefaultPage" and make the
 * default-page markers unmatchable. Newline/tab/CR survive; everything else
 * becomes a space.
 */
export function probeBody(raw: string, max = 4096): string {
  // eslint-disable-next-line no-control-regex
  return String(raw ?? "").replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, " ").slice(0, max);
}

/**
 * A response body shorter than this (after trimming) is not a website. A real
 * page — even a JavaScript app whose HTML is just a mount point — is hundreds of
 * bytes; a truly empty 200 is what a misrouted vhost or an empty document root
 * returns. Deliberately measured on the RAW body, not on stripped-tag "visible
 * text": a React/Next shell has almost no visible text and must NOT be flagged.
 */
export const NEAR_EMPTY_BODY_BYTES = 64;

/**
 * The stock pages a freshly-installed web server serves when NOTHING has claimed
 * the request. Every one of these answers 200, which is why the old
 * "make a real request to each domain" check passed for a dead site.
 *
 * Real incident, 2026-07-25: the run reported the customer's main site as
 * serving. The browser showed a certificate warning and then the Apache2 Debian
 * Default Page — apache2 had been re-enabled from the source and was answering
 * on a port our generated nginx config was supposed to own. A 200 from the
 * distribution's placeholder is a FAILED migration, not a successful one.
 */
export const DEFAULT_PAGE_MARKERS: { re: RegExp; what: string }[] = [
  { re: /Apache2\s+Debian\s+Default\s+Page/i, what: "the Apache2 Debian default page" },
  { re: /Apache2\s+Ubuntu\s+Default\s+Page/i, what: "the Apache2 Ubuntu default page" },
  { re: /Apache\s+HTTP\s+Server\s+Test\s+Page/i, what: "the stock Apache test page" },
  // The classic /var/www/html/index.html: `<html><body><h1>It works!</h1></body></html>`.
  // Anchored on the heading so a real site that merely contains the words
  // "it works!" in its copy is never mistaken for a placeholder.
  { re: /<h1>\s*It\s+works!\s*<\/h1>/i, what: `Apache's stock "It works!" page` },
  { re: /Welcome\s+to\s+nginx!/i, what: `nginx's stock "Welcome to nginx!" page` },
];

/**
 * Why this response is a placeholder rather than the customer's site, or "" when
 * it looks like real content. Content is only judged on a 2xx: a 301 to HTTPS or
 * a 401/404 legitimately has a tiny (or empty) body and the status alone already
 * proves the vhost matched.
 */
export function defaultPageReason(code: string, body: string): string {
  if (!/^2\d\d$/.test(code)) return "";
  for (const m of DEFAULT_PAGE_MARKERS) {
    if (m.re.test(body)) return `it answered ${code} with ${m.what}, not your site`;
  }
  const t = body.trim();
  // A short JSON/XML body is an API answering correctly, not an empty site — a
  // vhost that legitimately returns `{"ok":true}` must never be called dark.
  const structured = t.startsWith("{") || t.startsWith("[") || t.startsWith("<?xml");
  if (!structured && t.length < NEAR_EMPTY_BODY_BYTES) {
    return `it answered ${code} with an empty page (${t.length} bytes) — whatever should be behind this name is not there`;
  }
  return "";
}

/**
 * The hostnames on the certificate this server actually presents for `domain`,
 * read with SNI so it is the same certificate a browser would be shown.
 * `null` means we could not determine it (no openssl, or nothing on 443) — an
 * unknown is never treated as a failure.
 *
 * Real incident, 2026-07-25: studionexis.com was served nexis.revsports.ca's
 * certificate, so every visitor got ERR_CERT_COMMON_NAME_INVALID before they
 * ever reached the site — and the run reported that domain as serving, because
 * the probe used `-k` and only looked at the status code.
 */
async function servedCertNames(conn: Client, domain: string): Promise<string[] | null> {
  if (!DOMAIN_RE.test(domain)) return null;
  const r = await sh(
    conn,
    `T=$(command -v timeout >/dev/null 2>&1 && echo 'timeout 8'); ` +
      `command -v openssl >/dev/null 2>&1 || exit 3; ` +
      `$T openssl s_client -connect 127.0.0.1:443 -servername ${domain} </dev/null 2>/dev/null ` +
      `| openssl x509 -noout -subject -ext subjectAltName 2>/dev/null`,
    SETUP_TIMEOUT_MS
  );
  const out = probeBody(r.stdout, 4096);
  if (!out.trim()) return null;
  const names: string[] = [];
  // `subject=CN = example.com`, `subject= /C=US/CN=example.com`, `CN=example.com`.
  const cn = /CN\s*=\s*([^,/\r\n]+)/.exec(out);
  if (cn) names.push(cn[1].trim());
  for (const m of out.matchAll(/DNS:\s*([^,\s]+)/g)) names.push(m[1].trim());
  const uniq = [...new Set(names.map((n) => n.toLowerCase().replace(/\.$/, "")).filter(Boolean))].slice(0, 40);
  return uniq.length ? uniq : null;
}

/** Does a certificate carrying `certNames` cover `domain`? (`*.x` = ONE label.) */
export function certCoversName(certNames: string[], domain: string): boolean {
  const d = domain.toLowerCase().replace(/\.$/, "");
  for (const n of certNames) {
    if (n === d) return true;
    if (n.startsWith("*.")) {
      const base = n.slice(2);
      const dot = d.indexOf(".");
      if (base && dot > 0 && d.slice(dot + 1) === base) return true;
    }
  }
  return false;
}

/**
 * "Serving" means the web stack answered with an HTTP status — 200/301/401/404
 * all prove the port is bound, the vhost matched and something is behind it.
 * Only a connection failure (000) or a 5xx counts as not serving.
 *
 * This is necessary but NOT sufficient — see defaultPageReason and
 * servedCertNames for the two ways a 200 still means a dead site.
 */
export function isServing(code: string): boolean {
  return /^[1-4]\d\d$/.test(code);
}

// ---- THE SCORE ------------------------------------------------------------
/**
 * Everything the final outcome is computed from. Deliberately a plain data
 * structure with no `Client`, no SSH and no clock: the scoring rule is the one
 * piece of this engine that decides what the customer is TOLD, and it was wrong
 * in production for months (`Sites actually serving: 4/4` with six domains
 * dark). A rule that cannot be run in a test is a rule nobody can check, so it
 * is extracted here and exercised by `test/migration-gate.test.ts` instead of
 * only ever being exercised by a real customer's cutover.
 */
export type MigrationScoreInput = {
  /**
   * Every hostname the SOURCE server answered on, from its own live vhost
   * config. THE DENOMINATOR. Empty means the source inventory could not be read
   * — we then have no honest denominator and say so rather than scoring
   * ourselves against our own homework.
   */
  sourceDomains: string[];
  /** The names actually probed (the probe budget caps this below sourceDomains). */
  probeNames: string[];
  /** Per-domain probe verdicts. Only `serving: true` counts towards the score. */
  siteProbes: { domain: string; serving: boolean }[];
  /** Units the exec pre-flight / health gate refused to certify as running. */
  unitBlockers: { domain: string }[];
};

export type MigrationScore = {
  /** The set the score was measured against (sourceDomains, or probeNames as a named fallback). */
  scoredAgainst: string[];
  /** How many of `scoredAgainst` are serving. */
  servingCount: number;
  /** Everything in `scoredAgainst` that is not serving — failed AND unchecked. */
  unservedDomains: string[];
  /** Unserved names we DID probe: these are known-broken. */
  failedProbe: string[];
  /** Unserved names we never probed: "we did not check" is not "it works". */
  uncheckedDomains: string[];
  outcome: MigrationOutcome;
  outcomeReasons: string[];
};

/**
 * Decide the terminal outcome of a run. Extracted from `runRealMigration` so it
 * is testable in isolation — see MigrationScoreInput.
 *
 * The invariant that matters, and the one the 2026-07-25 run violated: this
 * function can return COMPLETED **only** when every hostname the old server
 * answered on serves here and every migrated unit is healthy. A denominator we
 * get to pick is not a measurement, so `sourceDomains` (read off the source)
 * wins over `probeNames` (chosen by us), and falling back to `probeNames` is
 * itself an outcome reason.
 */
export function judgeMigrationOutcome(input: MigrationScoreInput): MigrationScore {
  const servingSet = new Set(input.siteProbes.filter((p) => p.serving).map((p) => p.domain));
  const probedSet = new Set(input.probeNames);
  const scoredAgainst = input.sourceDomains.length ? input.sourceDomains : input.probeNames;

  // Everything the old server served that this one does not. A name we did not
  // get to probe counts here too — "we did not check" is not "it works" — but it
  // is worded separately so the customer is never told a site is broken when
  // what we actually mean is that we ran out of probe budget.
  const unservedDomains = scoredAgainst.filter((d) => !servingSet.has(d));
  const failedProbe = unservedDomains.filter((d) => probedSet.has(d));
  const uncheckedDomains = unservedDomains.filter((d) => !probedSet.has(d));

  // Anything on this list means the customer's move is NOT finished, however
  // many individual steps succeeded.
  const outcomeReasons: string[] = [];
  if (failedProbe.length) {
    outcomeReasons.push(
      `${failedProbe.length} of the ${scoredAgainst.length} domain(s) the old server answered on ${failedProbe.length === 1 ? "does" : "do"} not serve here: ${failedProbe.slice(0, 8).join(", ")}${failedProbe.length > 8 ? " …" : ""}`
    );
  }
  if (uncheckedDomains.length) {
    outcomeReasons.push(
      `${uncheckedDomains.length} domain(s) the old server answered on were not checked at all: ${uncheckedDomains.slice(0, 6).join(", ")}${uncheckedDomains.length > 6 ? " …" : ""}`
    );
  }
  if (input.unitBlockers.length) {
    outcomeReasons.push(
      `${input.unitBlockers.length} migrated service(s) are not running: ${input.unitBlockers.slice(0, 5).map((b) => b.domain).join(", ")}${input.unitBlockers.length > 5 ? " …" : ""}`
    );
  }
  if (!input.sourceDomains.length && input.probeNames.length) {
    outcomeReasons.push(
      "the old server's live configuration could not be read, so this score is measured against the sites we published rather than against everything the old server served — check the rest by hand"
    );
  }

  return {
    scoredAgainst,
    servingCount: scoredAgainst.filter((d) => servingSet.has(d)).length,
    unservedDomains,
    failedProbe,
    uncheckedDomains,
    outcome: outcomeReasons.length ? "COMPLETED_WITH_ISSUES" : "COMPLETED",
    outcomeReasons,
  };
}

