export async function runRealMigration(input: RealMigrationInput): Promise<RealMigrationSummary> {
  const { migration, target, items, report } = input;
  assert(target, "target server row not found");

  // ---- 1. Validate EVERY non-secret input up front (fail closed) ----------
  const host = migration.sourceHost;
  const port = migration.sourcePort;
  const user = migration.sourceUser;
  assert(validHost(host), "source host is not a valid hostname or IP address");
