/** Write bytes to a remote file over SFTP with a fixed 0600 mode (no shell). */
function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const ws = sftp.createWriteStream(path, { mode: 0o600 });
    ws.on("close", () => resolve());
    ws.on("error", (e: Error) => reject(e));
    ws.end(Buffer.from(content, "utf8"));
  });
}

function connectTarget(server: TargetServer): Promise<{ conn: Client; sftp: SFTPWrapper }> {
  return new Promise((resolve, reject) => {
    const target = connectionTarget(server as any);
    if (!target) return reject(new Error("target server is not reachable yet — connection details are pending"));
    const password = serverRootPassword(server);
    if (!password) return reject(new Error("target server has no root password on record"));
    const conn = new Client();
    conn.on("ready", () => {
      conn.sftp((err, sftp) => {
        if (err) return reject(err);
        resolve({ conn, sftp });
      });
    });
    conn.on("error", (e) => reject(e instanceof Error ? e : new Error(String(e))));
    conn.connect({
      host: target.host,
      port: target.port,
      username: "root",
      password,
      readyTimeout: CONNECT_TIMEOUT_MS,
    });
  });
}

